// Isolation test (OS-12) — construct ConditionIdentities with its declared inputs and nothing
// else, then exercise every public operation. (Generated by new-object.py, rewritten for
// strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import type { DigestPort } from "../src/ports/index.js";
import { ConditionIdentities } from "../src/condition/index.js";

const one: DigestPort = { digest: (b) => `one:${Array.from(b).join(",")}` };
const other: DigestPort = { digest: (b) => `other:${Array.from(b).join(",")}` };
const inputs = { prompt: "p", references: ["r"] };

describe("ConditionIdentities in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new ConditionIdentities({} as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new ConditionIdentities({ digests: {} as never })).toThrow();
  });

  it("identityOf answers differently when digests differs", () => {
    expect(new ConditionIdentities({ digests: one }).identityOf(inputs)).not.toEqual(new ConditionIdentities({ digests: other }).identityOf(inputs));
  });

  it("sameCondition answers exact equality, whatever the digest", () => {
    const a = new ConditionIdentities({ digests: one });
    expect([a.sameCondition(a.identityOf(inputs), a.identityOf(inputs)), a.sameCondition(a.identityOf(inputs), a.identityOf({ prompt: "q" }))]).toEqual([true, false]);
  });
});
